sp_header_footer.client_script:
api.controller=function($scope) {
  /* widget controller */
  var c = this;
  var gform = $scope.page.g_form;
  c.steps = ['Step1', 'Step2', 'Step3', 'Step4', 'Step5'];
  c.currentStep = 0;

  c.selectStep = function(index){
	c.currentStep = index;
	gform.setValue('current_section', index);
  }
};

sp_header_footer.css:
.steps {
	display: flex;
  list-style: none;
  padding: 0;
  margin: 0;
  border: 1px solid #ccc;
	border-radius: 4px;
  overflow: hidden;
}
.steps .home-step {
	flex: 0 0 auto;
  padding: 10px 5px;
  background: #f9f9f9;
  border-right: 1px solid #ccc;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 48px;
  height: 100%;
}
.steps .home-step img {
	width: 20px;
  height: 20px;
}
.step li {
  position: relative;
  flex: 1;
  padding: 10px 20px;
  text-align: center;
  background: #fff;
  cursor: pointer;
}
.step li::before {
  content: '';
  position: absolute;
  top: 0;
 height: -20px;
}
